window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2878d98c984af3b9"]={"versions": [{"id": "FIG-2878d98c984af3b9", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm und Transformationsmuster der AUTOSAR Generic Structure Template (TPS Generic Structure Template). Das Diagramm stellt das Entwurfsmuster („Pattern to implement references“) gegenüber, wie eine logische Assoziation aus dem reinen Metamodell („pure meta model (needs no annotation)“) in die XML-Schema-Repräsentation des erweiterten Metamodells („extended meta model“) transformiert bzw. generiert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Im Paket <code>pure meta model (needs no annotation)</code> existieren die Klassen <code>{Referrer}</code>, die Zielklasse <code>Target</code> mit dem Stereotyp bzw. der Eigenschaft <code>Referrable</code> sowie der Primitivtyp <code>«primitive» PrimitiveTypes::Ref</code> mit den Attributen <code>+ base: Identifier [0..1]</code> und <code>+ index: PositiveInteger [0..1]</code>. Zwischen <code>{Referrer}</code> und <code>Target</code> besteht eine gerichtete Assoziation mit der Zielrolle <code>+{theRole}</code> und der Kardinalität <code>{multiplicity}</code>. Separat dargestellt ist das Aufzählungs- bzw. Hilfselement <code>{Target}SubtypesEnum</code>.</p>\n<p class=\"fig-p\">Im Paket <code>extended meta model</code> umfasst die Struktur die Klasse <code>{Referrer}</code>, die über eine gerichtete Komposition mit der Rolle <code>+{theRole}Ref</code> und der Kardinalität <code>{multiplicity}</code> eine anonyme Klasse <code>&lt;anonymous&gt;</code> aggregiert. <code>&lt;anonymous&gt;</code> besitzt das Attribut <code>+ dest: {Target}SubtypesEnum</code> und erbt via Generalisierung (<code>extension base</code>) von der Klasse <code>Ref</code>. Die Klasse <code>Ref</code> weist die Attribute <code>+ base: Identifier [0..1]</code>, <code>+ index: PositiveInteger</code> und <code>+ reference: Ref_simple</code> auf. Eine weitere Klasse <code>Ref_simple</code> dient als Zieltyp bzw. Basiselement für einfache Referenzen. Zugehörige Notizen spezifizieren UML-Tags für Attribute und Assoziationen (u. a. <code>xml.attribute: true</code>, <code>xml.name</code>, <code>xml.namePlural</code>, <code>xml.roleWrapperElement</code>, <code>xml.roleElement=true</code>, <code>xml.typeWrapperElementfalse</code>, <code>xml.typeElement=false</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt eine strukturelle Modelltransformation (<code>«generates»</code>):</p>\n<ol class=\"fig-list\"><li>Eine im reinen Metamodell definierte Assoziation von <code>{Referrer}</code> auf ein referenzierbares Ziel (<code>Target</code>) wird in eine Kompositionsbeziehung im erweiterten Metamodell überführt.\n</li><li>Anstelle einer direkten Zeigerbeziehung instanziiert <code>{Referrer}</code> ein anonymes Referenzelement <code>&lt;anonymous&gt;</code>.\n</li><li>Das Ziel der Referenz wird über das XML-Attribut <code>dest</code> typisiert (<code>{Target}SubtypesEnum</code>).\n</li><li>Durch Vererbung von <code>Ref</code> erhält das Referenzelement die Identifikations- und Lokalisierungseigenschaften (<code>base</code>, <code>index</code>) sowie den Verweiswert über <code>reference</code> (<code>Ref_simple</code>).\n</li><li>Abhängigkeitsbeziehungen (<code>«generates»</code> und gestrichelte Pfeile) bilden <code>PrimitiveTypes::Ref</code> auf <code>Ref</code> sowie dessen Wertanteil auf <code>Ref_simple</code> ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Muster definiert die verbindliche schema- und serialisierungstechnische Umsetzung aller AUTOSAR-Referenzen in ARXML:</p>\n<ul class=\"fig-list\"><li>Referenzen werden im Schema nicht als native IDREFs, sondern als strukturierte Wrapper-Elemente mit Pfad- bzw. Namensauflösung realisiert.\n</li><li>Das Attribut <code>dest</code> ist zwingend als XML-Attribut (<code>xml.attribute: true</code>) zu serialisieren und schränkt den Zieltyp auf gültige Subtypen von <code>Target</code> ein.\n</li><li>Die UML-Tags steuern die Generierung der Wrapper- und Rollenelemente (<code>roleWrapperElement</code>, <code>roleElement</code>, <code>typeWrapperElement</code>, <code>typeElement</code>).\n</li><li>Das Attribut <code>index</code> in <code>Ref</code> ist mit fester Multiplizität 1 spezifiziert, <code>base</code> ist optional (<code>[0..1]</code>). <code>&lt;anonymous&gt;</code> existiert ausschließlich im Schema („This is an anoymuous class avaliable only in the schema“).\n</li></ul>"}, {"id": "FIG-6ecdccbae92415fe", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm und Transformationsmuster der AUTOSAR Generic Structure Template (TPS Generic Structure Template). Das Diagramm stellt das Entwurfsmuster („Pattern to implement references“) gegenüber, wie eine logische Assoziation aus dem reinen Metamodell („pure meta model (needs no annotation)“) in die XML-Schema-Repräsentation des erweiterten Metamodells („extended meta model“) transformiert bzw. generiert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Im Paket <code>pure meta model (needs no annotation)</code> existieren die Klassen <code>{Referrer}</code>, die Zielklasse <code>Target</code> mit der Eigenschaft <code>Referrable</code> sowie der Primitivtyp <code>«primitive» PrimitiveTypes::Ref</code> mit den Attributen <code>+ base :Identifier [0..1]</code> und <code>+ index :PositiveInteger [0..1]</code>. Zwischen <code>{Referrer}</code> und <code>Target</code> besteht eine gerichtete Assoziation mit der Zielrolle <code>+{theRole}</code> und der Multiplizität <code>{multiplicity}</code>. Separat dargestellt ist <code>{Target}SubtypesEnum</code>.</p>\n<p class=\"fig-p\">Im Paket <code>extended meta model</code> aggregiert <code>{Referrer}</code> über eine gerichtete Komposition mit der Rolle <code>+{theRole}Ref</code> und der Multiplizität <code>{multiplicity}</code> die Klasse <code>&lt;anonymous&gt;</code>. Diese besitzt das Attribut <code>+ dest :{Target}SubtypesEnum</code> und leitet über Generalisierung (<code>extension base</code>) von <code>Ref</code> ab. Die Klasse <code>Ref</code> weist die Attribute <code>+ base :Identifier [0..1]</code>, <code>+ index :PositiveInteger [0..1]</code> und <code>+ value :Ref_simple</code> auf. Eine separate Klasse <code>Ref_simple</code> repräsentiert den Referenzwert. Notizen dokumentieren UML-Tags für Attribute und Assoziationen (<code>xml.attribute: true</code>, XML-Namenssteuerung sowie <code>xml.roleWrapperElement=true</code>, <code>xml.roleElement=true</code>, <code>xml.typeWrapperElementfalse</code>, <code>xml.typeElement=false</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt eine strukturelle Modelltransformation (<code>«generates»</code>):</p>\n<ol class=\"fig-list\"><li>Eine im reinen Metamodell definierte Assoziation von <code>{Referrer}</code> auf ein referenzierbares Ziel (<code>Target</code>) wird in eine Kompositionsbeziehung im erweiterten Metamodell überführt.\n</li><li>Anstelle einer direkten Zeigerbeziehung instanziiert <code>{Referrer}</code> ein anonymes Referenzelement <code>&lt;anonymous&gt;</code>.\n</li><li>Das Ziel der Referenz wird über das XML-Attribut <code>dest</code> typisiert (<code>{Target}SubtypesEnum</code>).\n</li><li>Durch Vererbung von <code>Ref</code> erhält das Referenzelement die Identifikations- und Lokalisierungseigenschaften (<code>base</code>, <code>index</code>) sowie den Verweiswert über <code>reference</code> (<code>Ref_simple</code>).\n</li><li>Abhängigkeitsbeziehungen (<code>«generates»</code> und gestrichelte Pfeile) bilden <code>PrimitiveTypes::Ref</code> auf <code>Ref</code> sowie dessen Wertanteil auf <code>Ref_simple</code> ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Muster definiert die verbindliche schema- und serialisierungstechnische Umsetzung aller AUTOSAR-Referenzen in ARXML:</p>\n<ul class=\"fig-list\"><li>Referenzen werden im Schema als strukturierte Wrapper-Elemente abgebildet.\n</li><li>Der eigentliche Referenzwert innerhalb von <code>Ref</code> wird über das Attribut <code>value</code> vom Typ <code>Ref_simple</code> gehalten.\n</li><li>Das Attribut <code>index</code> in <code>Ref</code> ist optional mit der Kardinalität <code>[0..1]</code> modelliert (korrespondierend zu <code>base [0..1]</code>).\n</li><li>Das Attribut <code>dest</code> wird als XML-Attribut (<code>xml.attribute: true</code>) serialisiert und bestimmt den genauen Zieltyp über <code>{Target}SubtypesEnum</code>.\n</li><li>Die UML-Tags steuern die Erzeugung von Rollen- und Typ-Wrappern im XML-Schema. <code>&lt;anonymous&gt;</code> ist eine rein schemabezogene Hilfsklasse.\n</li></ul>"}, {"id": "FIG-c3831ffb3bbfdfa3", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm und Transformationsmuster der AUTOSAR Generic Structure Template (TPS Generic Structure Template). Das Diagramm stellt das Entwurfsmuster („Pattern to implement references“) gegenüber, wie eine logische Assoziation aus dem reinen Metamodell („pure meta model (needs no annotation)“) in die XML-Schema-Repräsentation des erweiterten Metamodells („extended meta model“) transformiert bzw. generiert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Im Paket <code>pure meta model (needs no annotation)</code> existieren die Klassen <code>{Referrer}</code>, die Zielklasse <code>Target</code> mit der Eigenschaft <code>Referrable</code> sowie der Primitivtyp <code>«primitive» PrimitiveTypes::Ref</code> mit den Attributen <code>+ base :Identifier [0..1]</code> und <code>+ index :PositiveInteger [0..1]</code>. Zwischen <code>{Referrer}</code> und <code>Target</code> besteht eine gerichtete Assoziation mit der Zielrolle <code>+{theRole}</code> und der Multiplizität <code>{multiplicity}</code>. Separat dargestellt ist <code>{Target}SubtypesEnum</code>.</p>\n<p class=\"fig-p\">Im Paket <code>extended meta model</code> aggregiert <code>{Referrer}</code> über eine gerichtete Komposition mit der Rolle <code>+{theRole}Ref</code> und der Multiplizität <code>{multiplicity}</code> die Klasse <code>&lt;anonymous&gt;</code>. Diese besitzt das Attribut <code>+ dest :{Target}SubtypesEnum</code> und leitet über Generalisierung (<code>extension base</code>) von <code>Ref</code> ab. Die Klasse <code>Ref</code> weist die Attribute <code>+ base :Identifier [0..1]</code>, <code>+ index :PositiveInteger [0..1]</code> und <code>+ value :Ref_simple</code> auf. Eine separate Klasse <code>Ref_simple</code> repräsentiert den Referenzwert. Notizen dokumentieren UML-Tags für Attribute und Assoziationen (<code>xml.attribute: true</code>, XML-Namenssteuerung sowie <code>xml.roleWrapperElement=true</code>, <code>xml.roleElement=true</code>, <code>xml.typeWrapperElementfalse</code>, <code>xml.typeElement=false</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt eine strukturelle Modelltransformation (<code>«generates»</code>):</p>\n<ol class=\"fig-list\"><li>Eine im reinen Metamodell definierte Assoziation von <code>{Referrer}</code> auf ein referenzierbares Ziel (<code>Target</code>) wird in eine Kompositionsbeziehung im erweiterten Metamodell überführt.\n</li><li>Anstelle einer direkten Zeigerbeziehung instanziiert <code>{Referrer}</code> ein anonymes Referenzelement <code>&lt;anonymous&gt;</code>.\n</li><li>Das Ziel der Referenz wird über das XML-Attribut <code>dest</code> typisiert (<code>{Target}SubtypesEnum</code>).\n</li><li>Durch Vererbung von <code>Ref</code> erhält das Referenzelement die Identifikations- und Lokalisierungseigenschaften (<code>base</code>, <code>index</code>) sowie den Verweiswert über <code>reference</code> (<code>Ref_simple</code>).\n</li><li>Abhängigkeitsbeziehungen (<code>«generates»</code> und gestrichelte Pfeile) bilden <code>PrimitiveTypes::Ref</code> auf <code>Ref</code> sowie dessen Wertanteil auf <code>Ref_simple</code> ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Muster definiert die verbindliche schema- und serialisierungstechnische Umsetzung aller AUTOSAR-Referenzen in ARXML:</p>\n<ul class=\"fig-list\"><li>Referenzen werden im Schema als strukturierte Wrapper-Elemente abgebildet.\n</li><li>Der eigentliche Referenzwert innerhalb von <code>Ref</code> wird über das Attribut <code>value</code> vom Typ <code>Ref_simple</code> gehalten.\n</li><li>Das Attribut <code>index</code> in <code>Ref</code> ist optional mit der Kardinalität <code>[0..1]</code> modelliert (korrespondierend zu <code>base [0..1]</code>).\n</li><li>Das Attribut <code>dest</code> wird als XML-Attribut (<code>xml.attribute: true</code>) serialisiert und bestimmt den genauen Zieltyp über <code>{Target}SubtypesEnum</code>.\n</li><li>Die UML-Tags steuern die Erzeugung von Rollen- und Typ-Wrappern im XML-Schema. <code>&lt;anonymous&gt;</code> ist eine rein schemabezogene Hilfsklasse.\n</li></ul>"}, {"id": "FIG-fd9db1c31f3df4cf", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm und Transformationsmuster der AUTOSAR Generic Structure Template (TPS Generic Structure Template). Das Diagramm stellt das Entwurfsmuster („Pattern to implement references“) gegenüber, wie eine logische Assoziation aus dem reinen Metamodell („pure meta model (needs no annotation)“) in die XML-Schema-Repräsentation des erweiterten Metamodells („extended meta model“) transformiert bzw. generiert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Im Paket <code>pure meta model (needs no annotation)</code> existieren die Klassen <code>{Referrer}</code>, die Zielklasse <code>Target</code> mit der Eigenschaft <code>Referrable</code> sowie der Primitivtyp <code>«primitive» PrimitiveTypes::Ref</code> mit den Attributen <code>+ base :Identifier [0..1]</code> und <code>+ index :PositiveInteger [0..1]</code>. Zwischen <code>{Referrer}</code> und <code>Target</code> besteht eine gerichtete Assoziation mit der Zielrolle <code>+{theRole}</code> und der Multiplizität <code>{multiplicity}</code>. Separat dargestellt ist <code>{Target}SubtypesEnum</code>.</p>\n<p class=\"fig-p\">Im Paket <code>extended meta model</code> aggregiert <code>{Referrer}</code> über eine gerichtete Komposition mit der Rolle <code>+{theRole}Ref</code> und der Multiplizität <code>{multiplicity}</code> die Klasse <code>&lt;anonymous&gt;</code>. Diese besitzt das Attribut <code>+ dest :{Target}SubtypesEnum</code> und leitet über Generalisierung (<code>extension base</code>) von <code>Ref</code> ab. Die Klasse <code>Ref</code> weist die Attribute <code>+ base :Identifier [0..1]</code>, <code>+ index :PositiveInteger [0..1]</code> und <code>+ value :Ref_simple</code> auf. Eine separate Klasse <code>Ref_simple</code> repräsentiert den Referenzwert. Notizen dokumentieren UML-Tags für Attribute und Assoziationen (<code>xml.attribute: true</code>, XML-Namenssteuerung sowie <code>xml.roleWrapperElement=true</code>, <code>xml.roleElement=true</code>, <code>xml.typeWrapperElementfalse</code>, <code>xml.typeElement=false</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt eine strukturelle Modelltransformation (<code>«generates»</code>):</p>\n<ol class=\"fig-list\"><li>Eine im reinen Metamodell definierte Assoziation von <code>{Referrer}</code> auf ein referenzierbares Ziel (<code>Target</code>) wird in eine Kompositionsbeziehung im erweiterten Metamodell überführt.\n</li><li>Anstelle einer direkten Zeigerbeziehung instanziiert <code>{Referrer}</code> ein anonymes Referenzelement <code>&lt;anonymous&gt;</code>.\n</li><li>Das Ziel der Referenz wird über das XML-Attribut <code>dest</code> typisiert (<code>{Target}SubtypesEnum</code>).\n</li><li>Durch Vererbung von <code>Ref</code> erhält das Referenzelement die Identifikations- und Lokalisierungseigenschaften (<code>base</code>, <code>index</code>) sowie den Verweiswert über <code>reference</code> (<code>Ref_simple</code>).\n</li><li>Abhängigkeitsbeziehungen (<code>«generates»</code> und gestrichelte Pfeile) bilden <code>PrimitiveTypes::Ref</code> auf <code>Ref</code> sowie dessen Wertanteil auf <code>Ref_simple</code> ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Muster definiert die verbindliche schema- und serialisierungstechnische Umsetzung aller AUTOSAR-Referenzen in ARXML:</p>\n<ul class=\"fig-list\"><li>Referenzen werden im Schema als strukturierte Wrapper-Elemente abgebildet.\n</li><li>Der eigentliche Referenzwert innerhalb von <code>Ref</code> wird über das Attribut <code>value</code> vom Typ <code>Ref_simple</code> gehalten.\n</li><li>Das Attribut <code>index</code> in <code>Ref</code> ist optional mit der Kardinalität <code>[0..1]</code> modelliert (korrespondierend zu <code>base [0..1]</code>).\n</li><li>Das Attribut <code>dest</code> wird als XML-Attribut (<code>xml.attribute: true</code>) serialisiert und bestimmt den genauen Zieltyp über <code>{Target}SubtypesEnum</code>.\n</li><li>Die UML-Tags steuern die Erzeugung von Rollen- und Typ-Wrappern im XML-Schema. <code>&lt;anonymous&gt;</code> ist eine rein schemabezogene Hilfsklasse.\n</li></ul>"}, {"id": "FIG-d8aec1c4d04416ae", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm und Transformationsmuster der AUTOSAR Generic Structure Template (TPS Generic Structure Template). Das Diagramm stellt das Entwurfsmuster („Pattern to implement references“) gegenüber, wie eine logische Assoziation aus dem reinen Metamodell („pure meta model (needs no annotation)“) in die XML-Schema-Repräsentation des erweiterten Metamodells („extended meta model“) transformiert bzw. generiert wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Im Paket <code>pure meta model (needs no annotation)</code> existieren die Klassen <code>{Referrer}</code>, die Zielklasse <code>Target</code> mit der Eigenschaft <code>Referrable</code> sowie der Primitivtyp <code>«primitive» PrimitiveTypes::Ref</code> mit den drei Attributen <code>+ base: Identifier [0..1]</code>, <code>+ blueprintValue: String [0..1]</code> und <code>+ index: PositiveInteger [0..1]</code>. Zwischen <code>{Referrer}</code> und <code>Target</code> besteht eine gerichtete Assoziation mit der Zielrolle <code>+{theRole}</code> und der Multiplizität <code>{multiplicity}</code>. Separat dargestellt ist <code>{Target}SubtypesEnum</code>.</p>\n<p class=\"fig-p\">Im Paket <code>extended meta model</code> aggregiert <code>{Referrer}</code> über eine gerichtete Komposition mit der Rolle <code>+{theRole}Ref</code> und der Multiplizität <code>{multiplicity}</code> die Klasse <code>&lt;anonymous&gt;</code>. Diese besitzt das Attribut <code>+ dest: {Target}SubtypesEnum</code> und leitet über Generalisierung (<code>extension base</code>) von <code>Ref</code> ab. Die Klasse <code>Ref</code> weist die Attribute <code>+ base: Identifier [0..1]</code>, <code>+ index: PositiveInteger [0..1]</code> und <code>+ value: Ref_simple</code> auf. Eine separate Klasse <code>Ref_simple</code> repräsentiert den Referenzwert. Notizen dokumentieren UML-Tags für Attribute und Assoziationen (<code>xml.attribute: true</code>, XML-Namenssteuerung sowie <code>xml.roleWrapperElement=true</code>, <code>xml.roleElement=true</code>, <code>xml.typeWrapperElementfalse</code>, <code>xml.typeElement=false</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt eine strukturelle Modelltransformation (<code>«generates»</code>):</p>\n<ol class=\"fig-list\"><li>Eine im reinen Metamodell definierte Assoziation von <code>{Referrer}</code> auf ein referenzierbares Ziel (<code>Target</code>) wird in eine Kompositionsbeziehung im erweiterten Metamodell überführt.\n</li><li>Anstelle einer direkten Zeigerbeziehung instanziiert <code>{Referrer}</code> ein anonymes Referenzelement <code>&lt;anonymous&gt;</code>.\n</li><li>Das Ziel der Referenz wird über das XML-Attribut <code>dest</code> typisiert (<code>{Target}SubtypesEnum</code>).\n</li><li>Durch Vererbung von <code>Ref</code> erhält das Referenzelement die Identifikations- und Lokalisierungseigenschaften (<code>base</code>, <code>index</code>) sowie den Verweiswert über <code>reference</code> (<code>Ref_simple</code>).\n</li><li>Abhängigkeitsbeziehungen (<code>«generates»</code> und gestrichelte Pfeile) bilden <code>PrimitiveTypes::Ref</code> auf <code>Ref</code> sowie dessen Wertanteil auf <code>Ref_simple</code> ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Muster definiert die verbindliche schema- und serialisierungstechnische Umsetzung aller AUTOSAR-Referenzen in ARXML:</p>\n<ul class=\"fig-list\"><li>Der Basistyp <code>PrimitiveTypes::Ref</code> unterstützt neben der Standard-Pfadreferenzierung (<code>base</code>, <code>index</code>) optional das Attribut <code>blueprintValue: String [0..1]</code> für Referenzen im Kontext von Blueprints bzw. Entwurfsvorlagen.\n</li><li>Der eigentliche Referenzwert innerhalb der Schema-Klasse <code>Ref</code> wird über <code>value</code> (<code>Ref_simple</code>) geführt; <code>base</code> und <code>index</code> besitzen jeweils die optionale Multiplizität <code>[0..1]</code>.\n</li><li>Das Attribut <code>dest</code> wird als XML-Attribut serialisiert (<code>xml.attribute: true</code>) und bindet den Zieltyp an <code>{Target}SubtypesEnum</code>.\n</li><li>UML-Tags steuern die Generierung der ARXML-Rollen- und Typelemente. <code>&lt;anonymous&gt;</code> verbleibt eine reine Hilfsklasse auf Schemaebene.\n</li></ul>"}], "trans": [{"from": "FIG-2878d98c984af3b9", "to": "FIG-6ecdccbae92415fe", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In Klasse <code>Ref</code> im Bereich <code>extended meta model</code>: Attribut <code>+ reference: Ref_simple</code> umbenannt in <code>+ value :Ref_simple</code>.\n</li><li>In Klasse <code>Ref</code> im Bereich <code>extended meta model</code>: Kardinalität des Attributs <code>index</code> geändert von <code>PositiveInteger</code> (implizit <code>1</code>) auf <code>PositiveInteger [0..1]</code>.\n</li><li>Im Bereich <code>extended meta model</code>: Textsatz der Rollenbezeichnung und Multiplizität an der Kompositionskante zwischen <code>{Referrer}</code> und <code>&lt;anonymous&gt;</code> umgestellt von zweizeilig getrennt auf getrennte Platzierung von Rolle <code>+{theRole}Ref</code> und Multiplizität <code>{multiplicity}</code>.\n</li></ul>"}, {"from": "FIG-6ecdccbae92415fe", "to": "FIG-c3831ffb3bbfdfa3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c3831ffb3bbfdfa3", "to": "FIG-fd9db1c31f3df4cf", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-fd9db1c31f3df4cf", "to": "FIG-d8aec1c4d04416ae", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In Klasse <code>«primitive» PrimitiveTypes::Ref</code> im Bereich <code>pure meta model (needs no annotation)</code>: Attribut <code>+ blueprintValue: String [0..1]</code> neu eingefügt.\n</li></ul>"}]};
